svg.script:

(function() {
  // Anatomical Database with Precise Medical & Clinical Data
  var db = {
    "pubis": {
      title: "SÍNFISE PÚBICA",
      badge: "ÂNCORA ANTERIOR (ÓSSEA)",
      delancey: "Nível II / III (Ancoragem Anterior)",
      anchors: "Ramos Isquiopúbicos & Cartilagem Interpúbica",
      vector: "Vetor de fixação anterior rígida do Arco Tendíneo (ATLA) e Ligamentos Pubovesicais.",
      clinical: "Ponto fixo ventral. A separação diastásica pubiana no parto (>10mm) causa dor pélvica aguda e instabilidade de marcha.",
      status: "INTEGRIDADE ANATÔMICA NORMAL",
      statusColor: "var(--a12p22h-c-perineal-body)",
      layer: 1
    },
    "sacrum": {
      title: "PROMONTÓRIO SACRAL & CÓCCIX",
      badge: "ÂNCORA POSTERIOR (ÓSSEA)",
      delancey: "Nível I (Fixação Alta)",
      anchors: "Vertebras S1-S5 e Peças Coccígeas",
      vector: "Ancoragem do Ligamento Uterossacro e Músculo Coccígeo/Iliococcígeo.",
      clinical: "Promontório sacral (S1) é o ponto cego de fixação na Sacrocolpopexia laparoscópica. Atenção aos vasos sacrais médios!",
      status: "INTEGRIDADE ANATÔMICA NORMAL",
      statusColor: "var(--a12p22h-c-perineal-body)",
      layer: 1
    },
    "spine-r": {
      title: "ESPINHA ISQUIÁTICA DIREITA",
      badge: "ÂNCORA LATERAL (ÓSSEA)",
      delancey: "Ponto-Chave de Ancoragem de Sacroespinho",
      anchors: "Inserção Posterior do ATLA & Lig. Sacroespinhoso",
      vector: "Origem do M. Coccígeo e inserção posterior do Arco Tendíneo do Levantador do Ânus.",
      clinical: "Marco anatômico fundamental na Cirurgia Vaginal (Fixação ao Ligamento Sacroespinhoso / Sacrospinous Fixation) e Bloqueio do Pudendo.",
      status: "ZONA DE ANCORAGEM CIRÚRGICA",
      statusColor: "var(--a12p22h-c-ligament)",
      layer: 1
    },
    "spine-l": {
      title: "ESPINHA ISQUIÁTICA ESQUERDA",
      badge: "ÂNCORA LATERAL (ÓSSEA)",
      delancey: "Ponto-Chave de Ancoragem de Sacroespinho",
      anchors: "Inserção Posterior do ATLA & Lig. Sacroespinhoso",
      vector: "Origem do M. Coccígeo e inserção posterior do Arco Tendíneo do Levantador do Ânus.",
      clinical: "Marco anatômico fundamental na Cirurgia Vaginal (Fixação ao Ligamento Sacroespinhoso / Sacrospinous Fixation) e Bloqueio do Pudendo.",
      status: "ZONA DE ANCORAGEM CIRÚRGICA",
      statusColor: "var(--a12p22h-c-ligament)",
      layer: 1
    },
    "lig-uterosacral": {
      title: "LIGAMENTO UTEROSSACRO",
      badge: "CORDÃO POSTERIOR · NÍVEL I",
      delancey: "Nível I de DeLancey (Suspensão Apical)",
      anchors: "Colo Uterino / Cúpula Vaginal → Sacro (S2-S4)",
      vector: "Tração dórso-superior suspensória mantendo o eixo vaginal orientado para o sacro.",
      clinical: "A falha do Nível I causa Histerocele ou Prolapso de Cúpula Vaginal pós-histerectomia. Alvo da Uterossacropexia.",
      status: "SUSPENSÃO APICAL PRESERVADA",
      statusColor: "var(--a12p22h-c-perineal-body)",
      layer: 1
    },
    "lig-pubovesical": {
      title: "LIGAMENTO PUBOVESICOUTERINO",
      badge: "CORDÃO ANTERIOR · NÍVEL I",
      delancey: "Nível I de DeLancey (Estabilização Anterior)",
      anchors: "Face Posterior do Púbis → Junção Vesicouterina",
      vector: "Estabilização ântero-superior da base vesical e colo uterino.",
      clinical: "Evita o deslocamento posterior excessivo do colo e orienta a base da bexiga.",
      status: "INTEGRIDADE NORMAL",
      statusColor: "var(--a12p22h-c-perineal-body)",
      layer: 1
    },
    "lig-cardinal": {
      title: "LIGAMENTO CARDINAL (MACKENRODT)",
      badge: "CORDÃO LATERAL · NÍVEL I",
      delancey: "Nível I de DeLancey (Suspensão Lateral)",
      anchors: "Colo Uterino / Vagina Superior → Parede Pélvica Lateral",
      vector: "Condensação vascular/fascial que impede a descida vertical direta da cúpula.",
      clinical: "Contém os vasos uterinos na sua borda superior. Principal estrutura ligada na Histerectomia Radical.",
      status: "FORTE TENSÃO LATERAL",
      statusColor: "var(--a12p22h-c-ligament)",
      layer: 1
    },
    "atla": {
      title: "ARCO TENDÍNEO DO LEVANTADOR DO ÂNUS",
      badge: "ATLA · NÍVEL II DE DELANCEY",
      delancey: "Nível II (Fixação Lateral da Fáscia)",
      anchors: "Púbis Anterior → Espinha Isquiática Posterior",
      vector: "Espessamento da Fáscia Obturatória de onde se origina o M. Iliococcígeo e se fixa a Fáscia Endopélvica.",
      clinical: "A avulsão da Fáscia Endopélvica do ATLA resulta no Defeito Paravaginal (Cistocele Lateral), corrigido por Cirurgia de Burch ou slings.",
      status: "LINHA DE TENSÃO CRÍTICA",
      statusColor: "var(--a12p22h-c-ligament)",
      layer: 2
    },
    "puborectalis": {
      title: "MÚSCULO PUBORRETAL",
      badge: "ALÇA DE CONTINÊNCIA · DIAFRAGMA PÉLVICO",
      delancey: "Suporte Dinâmico / Fechamento do Hiato",
      anchors: "Corpo do Púbis (Bilateral) → Laço posterior em U na Junção Anorretal",
      vector: "Tração ântero-superior constante mantendo o Ângulo Anorretal em ~90°.",
      clinical: "ALVO CRÍTICO DE AVULSÃO NO PARTO VAGINAL! A laceração do Puborretal alarga o Hiato Levatoriano (>25 cm²), elevando em 3x o risco de prolapso grave.",
      status: "ZONA DE CARGA CRÍTICA (RISCO DE AVULSÃO)",
      statusColor: "var(--a12p22h-c-alert)",
      layer: 2
    },
    "pubococcygeus": {
      title: "MÚSCULO PUBOCOCCÍGEO",
      badge: "CORPO PRINCIPAL LEVANTADOR",
      delancey: "Suporte Profundo / Elevador da Bacia",
      anchors: "Púbis Medial → Rafe Anococcígea e Cóccix",
      vector: "Tração ventral-superior eleva o assoalho pélvico e comprime as vísceras contra o púbis.",
      clinical: "Responsável pelo tônus basal e contração voluntária no treino de Kegel.",
      status: "TÔNUS MUSCULAR PRESERVADO",
      statusColor: "var(--a12p22h-c-perineal-body)",
      layer: 2
    },
    "iliococcygeus": {
      title: "MÚSCULO ILIOCOCCÍGEO",
      badge: "PLANO DORSAL LEVANTADOR",
      delancey: "Suporte Profundo / Prato Levatoriano",
      anchors: "ATLA Lateral → Rafe Anococcígea e Cóccix",
      vector: "Forma o 'Prato Levatoriano' plano e horizontal onde repousam os órgãos pélvicos.",
      clinical: "A inclinação verticalizada do prato levatoriano reflete perda de tônus e precede o surgimento de prolapsos viscerais.",
      status: "PRATO HORIZONTALIZADO NORMAL",
      statusColor: "var(--a12p22h-c-perineal-body)",
      layer: 2
    },
    "coccygeus": {
      title: "MÚSCULO COCCÍGEO (ISQUIOCOCCÍGEO)",
      badge: "COMPREENSÃO POSTERIOR",
      delancey: "Suporte Profundo Posterior",
      anchors: "Espinha Isquiática → Sacro Inferior & Cóccix",
      vector: "Estabilização da articulação sacrococcígea e fechamento dorsal da bacia.",
      clinical: "Intimamente dorsal ao Iliococcígeo, corre em paralelo ao Ligamento Sacroespinhoso.",
      status: "INTEGRIDADE NORMAL",
      statusColor: "var(--a12p22h-c-perineal-body)",
      layer: 2
    },
    "fascia-endopelvic": {
      title: "FÁSCIA ENDOPÉLVICA",
      badge: "REVESTIMENTO & FIXAÇÃO · NÍVEL II",
      delancey: "Nível II de DeLancey (Fixação Vaginal Lateral)",
      anchors: "ATLA Lateral → Paredes Vaginais Anterior/Posterior",
      vector: "Malha conectiva contínua que fixa a parede vaginal anterior (Fáscia Pubocervical) e posterior (Fáscia Retovaginal).",
      clinical: "Rotura central provoca Cistocele Central (Distensão); avulsão lateral no ATLA provoca Cistocele Lateral (Deslocamento).",
      status: "TENSÃO CONTINUA PRESERVADA",
      statusColor: "var(--a12p22h-c-perineal-body)",
      layer: 3
    },
    "perineal-membrane": {
      title: "MEMBRANA PERINEAL",
      badge: "DIAFRAGMA UROGENITAL · NÍVEL III",
      delancey: "Nível III de DeLancey (Apoio Perineal)",
      anchors: "Ramos Isquiopúbicos Bilaterais",
      vector: "Lâmina fibrosa triangular que fecha o triângulo urogenital anterior.",
      clinical: "Dá suporte direto à uretra distal. Sua integridade previne a hipermobilidade do colo vesical na Incontinência Urinária de Esforço (IUE).",
      status: "SUPORTE URETRAL PRESERVADO",
      statusColor: "var(--a12p22h-c-perineal-body)",
      layer: 3
    },
    "perineal-body": {
      title: "CORPO PERINEAL (CTP)",
      badge: "NÓ DE CONVERGÊNCIA · NÍVEL III",
      delancey: "Nível III de DeLancey (Centro Tendíneo do Períneo)",
      anchors: "Fusão de 4 Músculos: Puborretal, Transverso Superficial, Bulboesponjoso e Esfíncter Anal",
      vector: "Âncora fibromuscular central que separa o triângulo urogenital do anal.",
      clinical: "Sofre lacerações frequentes no parto (3º e 4º graus). A perda do corpo perineal gera hiato entreaberto e Perineocele/Rectocele baixa.",
      status: "NÓ TENDÍNEO ÍNTACTO",
      statusColor: "var(--a12p22h-c-perineal-body)",
      layer: 4
    },
    "bulbospongiosus": {
      title: "MÚSCULO BULBOESPONJOSO",
      badge: "PLANO SUPERFICIAL PERINEAL",
      delancey: "Nível III (Eritor e Esfíncter Vaginal)",
      anchors: "Corpo Perineal → Clitóris e Ramos Púbicos",
      vector: "Compressão do bulbo do vestíbulo e auxílio na oclusão do introito vaginal.",
      clinical: "Comumente seccionado na Episiotomia Mediolateral.",
      status: "INTEGRIDADE NORMAL",
      statusColor: "var(--a12p22h-c-perineal-body)",
      layer: 4
    },
    "ischiocavernosus": {
      title: "MÚSCULO ISQUIOCAVERNOSO",
      badge: "PLANO SUPERFICIAL PERINEAL",
      delancey: "Nível III (Erétil)",
      anchors: "Tuberosidade Isquiática → Crura do Clitóris",
      vector: "Compressão dos pilares eréteis do clitóris.",
      clinical: "Limita-se lateralmente aos ramos isquiopúbicos.",
      status: "INTEGRIDADE NORMAL",
      statusColor: "var(--a12p22h-c-perineal-body)",
      layer: 4
    },
    "transverse-superficial": {
      title: "TRANSVERSO SUPERFICIAL DO PERÍNEO",
      badge: "ESTABILIZADOR TRANSVERSO",
      delancey: "Nível III (Base do Triângulo Urogenital)",
      anchors: "Tuberosidade Isquiática → Corpo Perineal",
      vector: "Fixação e estabilização transversal do Centro Tendíneo do Períneo.",
      clinical: "Mantém a posição centralizada do Corpo Perineal contra trações sagitais.",
      status: "ESTABILIZAÇÃO TRANSVERSAL PRESERVADA",
      statusColor: "var(--a12p22h-c-perineal-body)",
      layer: 4
    },
    "anal-sphincter": {
      title: "ESFÍNCTER EXTERNO DO ÂNUS (EAE)",
      badge: "CONTINÊNCIA FECAL SUPERFICIAL",
      delancey: "Nível III (Esfincteriano Dorsal)",
      anchors: "Corpo Perineal (Anterior) → Rafe Anococcígea (Posterior)",
      vector: "Oclusão voluntária contínua do canal anal.",
      clinical: "Lacerações de 3º grau envolvem o EAE; de 4º grau atingem a mucosa anal. Correção imediata por superposição (overlapping) ou topo-a-topo.",
      status: "ANEL ESFINCTERIANO ÍNTACTO",
      statusColor: "var(--a12p22h-c-perineal-body)",
      layer: 4
    }
  };

  // Quiz Questions Bank for Active Recognition Training
  var quizQuestions = [
    { id: "puborectalis", prompt: '"MÚSCULO PUBORRETAL" (Alça em U de Continência)' },
    { id: "atla", prompt: '"ARCO TENDÍNEO DO LEVANTADOR DO ÂNUS" (ATLA)' },
    { id: "perineal-body", prompt: '"CORPO PERINEAL" (Centro Tendíneo CTP)' },
    { id: "lig-uterosacral", prompt: '"LIGAMENTO UTEROSSACRO" (Cordão Posterior Nível I)' },
    { id: "pubis", prompt: '"SÍNFISE PÚBICA" (Âncora Óssea Anterior)' },
    { id: "iliococcygeus", prompt: '"MÚSCULO ILIOCOCCÍGEO" (Prato Levatoriano)' },
    { id: "fascia-endopelvic", prompt: '"FÁSCIA ENDOPÉLVICA" (Nível II de DeLancey)' }
  ];
  var quizIndex = 0;
  var currentMode = "all"; // "all", "1", "2", "3", "4", "quiz"

  var svg = document.getElementById("a12p22h-stage");
  var tooltip = document.getElementById("a12p22h-tooltip");
  var tooltipTxt = document.getElementById("a12p22h-tooltip-txt");

  // UI Elements in Left Panel
  var pTitle = document.getElementById("a12p22h-panel-title");
  var pBadge = document.getElementById("a12p22h-panel-badge");
  var pBadgeBg = document.getElementById("a12p22h-panel-badge-bg");
  var pDelancey = document.getElementById("a12p22h-panel-delancey");
  var pAnchors = document.getElementById("a12p22h-panel-anchors");
  var pVector = document.getElementById("a12p22h-panel-vector");
  var pClinical = document.getElementById("a12p22h-panel-clinical");
  var pStatusTxt = document.getElementById("a12p22h-panel-status-txt");
  var pStatusDot = document.getElementById("a12p22h-panel-status-dot");
  var pStatusBox = document.getElementById("a12p22h-panel-status-box");

  var pQuizBox = document.getElementById("a12p22h-panel-quiz-box");
  var quizPrompt = document.getElementById("a12p22h-quiz-prompt");
  var quizFeedback = document.getElementById("a12p22h-quiz-feedback");
  var quizNextBtn = document.getElementById("a12p22h-quiz-next-btn");

  // Helper: Update Left Panel with Item Data
  function selectStructure(id) {
    var data = db[id];
    if (!data) return;

    // Clear previous selection highlight
    var hotspots = svg.querySelectorAll(".a12p22h-hotspot");
    hotspots.forEach(function(h) { h.classList.remove("a12p22h-selected"); });

    // Highlight target elements matching data-id
    var selectedElements = svg.querySelectorAll('.a12p22h-hotspot[data-id="' + id + '"]');
    selectedElements.forEach(function(el) { el.classList.add("a12p22h-selected"); });

    // Update Panel Content
    pTitle.textContent = data.title;
    pBadge.textContent = data.badge;
    pDelancey.textContent = data.delancey;

    // Multi-line tspan helper
    setTSpanText(pAnchors, data.anchors);
    setTSpanText(pVector, data.vector);
    setTSpanText(pClinical, data.clinical);

    pStatusTxt.textContent = data.status;
    pStatusDot.setAttribute("fill", data.statusColor);
    pStatusBox.querySelector("rect").setAttribute("stroke", data.statusColor);
  }

  function setTSpanText(textEl, str) {
    while (textEl.firstChild) { textEl.removeChild(textEl.firstChild); }
    var lines = str.split("\n");
    if (lines.length === 1 && str.length > 38) {
      // auto wrap roughly by words
      var words = str.split(" ");
      lines = [];
      var cur = "";
      words.forEach(function(w) {
        if ((cur + " " + w).length > 36) {
          lines.push(cur);
          cur = w;
        } else {
          cur = (cur ? cur + " " + w : w);
        }
      });
      if (cur) lines.push(cur);
    }
    lines.forEach(function(l, idx) {
      var tspan = document.createElementNS("http://www.w3.org/2000/svg", "tspan");
      tspan.setAttribute("x", "0");
      tspan.setAttribute("dy", idx === 0 ? "0" : "15");
      tspan.textContent = l;
      textEl.appendChild(tspan);
    });
  }

  // Layer Filter Toggle Engine
  function setLayerMode(mode) {
    currentMode = mode;

    // Button Active State Styling
    var btnIds = ["all", "1", "2", "3", "4", "quiz"];
    btnIds.forEach(function(b) {
      var btn = document.getElementById("a12p22h-btn-layer-" + b);
      if (btn) {
        if (b === mode) btn.classList.add("a12p22h-active");
        else btn.classList.remove("a12p22h-active");
      }
    });

    // Layer Visibility Management
    var l1 = document.getElementById("a12p22h-layer-1");
    var l2 = document.getElementById("a12p22h-layer-2");
    var l3 = document.getElementById("a12p22h-layer-3");
    var l4 = document.getElementById("a12p22h-layer-4");

    var layers = [l1, l2, l3, l4];

    if (mode === "all" || mode === "quiz") {
      layers.forEach(function(l) { l.classList.remove("a12p22h-dimmed", "a12p22h-hidden"); });
    } else {
      var targetIdx = parseInt(mode, 10);
      layers.forEach(function(l, idx) {
        if (idx + 1 === targetIdx) {
          l.classList.remove("a12p22h-dimmed", "a12p22h-hidden");
        } else {
          l.classList.add("a12p22h-dimmed");
        }
      });
    }

    // Quiz Mode Toggle
    if (mode === "quiz") {
      pQuizBox.style.display = "block";
      initQuizQuestion();
    } else {
      pQuizBox.style.display = "none";
    }
  }

  // Quiz Engine
  function initQuizQuestion() {
    var q = quizQuestions[quizIndex];
    setTSpanText(quizPrompt, "Clique na estrutura solicitada:\n" + q.prompt);
    quizFeedback.textContent = "Aguardando sua seleção...";
    quizFeedback.setAttribute("fill", "var(--a12p22h-txt-muted)");
  }

  function handleQuizClick(clickedId) {
    var q = quizQuestions[quizIndex];
    if (clickedId === q.id) {
      quizFeedback.textContent = "✓ CORRETO! Excelente identificação anatômica.";
      quizFeedback.setAttribute("fill", "var(--a12p22h-c-perineal-body)");
      selectStructure(clickedId);
    } else {
      quizFeedback.textContent = "✕ Incorreto. Você clicou em " + (db[clickedId] ? db[clickedId].title : "outra estrutura") + ". Tente novamente!";
      quizFeedback.setAttribute("fill", "var(--a12p22h-c-alert)");
    }
  }

  // Mouse Follow Tooltip
  function handleMouseMove(evt) {
    var ctm = svg.getScreenCTM();
    if (!ctm) return;
    var pt = svg.createSVGPoint();
    pt.x = evt.clientX;
    pt.y = evt.clientY;
    var loc = pt.matrixTransform(ctm.inverse());

    tooltip.setAttribute("transform", "translate(" + (loc.x - 400) + ", " + (loc.y - 170) + ")");
  }

  // Attach Event Listeners to Layer Control Buttons
  var btnMap = {
    "a12p22h-btn-layer-all": "all",
    "a12p22h-btn-layer-1": "1",
    "a12p22h-btn-layer-2": "2",
    "a12p22h-btn-layer-3": "3",
    "a12p22h-btn-layer-4": "4",
    "a12p22h-btn-layer-quiz": "quiz"
  };

  Object.keys(btnMap).forEach(function(btnId) {
    var btn = document.getElementById(btnId);
    if (btn) {
      btn.addEventListener("click", function() { setLayerMode(btnMap[btnId]); });
      btn.addEventListener("keydown", function(e) {
        if (e.key === "Enter" || e.key === " ") { setLayerMode(btnMap[btnId]); }
      });
    }
  });

  // Attach Event Listeners to Hotspots
  var hotspots = svg.querySelectorAll(".a12p22h-hotspot");
  hotspots.forEach(function(h) {
    var id = h.getAttribute("data-id");

    h.addEventListener("mouseenter", function(e) {
      var item = db[id];
      if (item) {
        tooltipTxt.textContent = item.title;
        tooltip.style.opacity = "1";
      }
    });

    h.addEventListener("mouseleave", function() {
      tooltip.style.opacity = "0";
    });

    h.addEventListener("mousemove", handleMouseMove);

    h.addEventListener("click", function() {
      if (currentMode === "quiz") {
        handleQuizClick(id);
      } else {
        selectStructure(id);
      }
    });

    h.addEventListener("keydown", function(e) {
      if (e.key === "Enter" || e.key === " ") {
        if (currentMode === "quiz") {
          handleQuizClick(id);
        } else {
          selectStructure(id);
        }
      }
    });
  });

  if (quizNextBtn) {
    quizNextBtn.addEventListener("click", function() {
      quizIndex = (quizIndex + 1) % quizQuestions.length;
      initQuizQuestion();
    });
  }

  // Default Initialization
  selectStructure("puborectalis");
  setLayerMode("all");
})();
